/** Subjects an `invalidate` frame names. A reconnecting client resyncs all of them. */
export const Topic = Object.freeze({
  // the note/folder tree changed
  NOTES: 'notes',
  // tabs, active tab, or panel state changed
  SESSION: 'session',
  // the prompt library changed
  PROMPTS: 'prompts',
  // the open library changed
  LIBRARY: 'library',
  // a document's user_intent changed
  INTENT: 'intent',
})
/** @typedef {typeof Topic[keyof typeof Topic]} TopicName */

/** Every topic, for the blanket resync a client runs when its workspace socket reconnects. */
export const AllTopics = Object.freeze(Object.values(Topic))

