/** Command families — the namespace a `command` frame declares it is invoking within. */
export const CommandFamily = Object.freeze({
  AI: 'ai',
  UTIL: 'util',
})
/** @typedef {typeof CommandFamily[keyof typeof CommandFamily]} CommandFamilyName */

/**
 * Every registered verb, under the family it is invoked within. Commands ride
 * the `command` frame as DATA — a new command is not a new frame type — so this
 * is the only place the browser half learns which verbs exist.
 *
 * Keyed by the family's WIRE word, so `CommandWords[CommandFamily.AI]` reads.
 */
export const CommandWords = Object.freeze({
  'ai': Object.freeze({
    // Quick answer in a popup — nothing is added to the document
    BTW: 'btw',
    // File this document where the AI's evaluation says it belongs
    FILE: 'file',
    // Mark this document as kept, then file it
    KEEP_AND_FILE: 'keep-and-file',
    // Re-evaluate this document's title, summary and tags
    METADATA: 'metadata',
    // 3-bullet summary of document or selection
    SUMMARY: 'summary',
    // Extract open action items, TODOs, and decisions as a checklist
    TODO: 'todo',
  }),
  'util': Object.freeze({
    // Base64 encode/decode inline text, selection, or document
    BASE64: 'base64',
    // Go runtime info: OS, arch, CPUs, goroutines, memory
    ENV: 'env',
    // SHA-256 hash of inline text, selection, or document
    HASH: 'hash',
    // Decode & inspect a JWT header + payload (no signature verification)
    JWT: 'jwt',
    // Upgrade every document's block ids to UUIDs so blocks are addressable
    MIGRATE_IDS: 'migrate-ids',
    // Display current timestamp & date in all standard formats
    NOW: 'now',
    // Word count, character count, reading time & document metrics
    STATS: 'stats',
    // Generate a new random UUID v4
    UUID: 'uuid',
  }),
})

/** The route prefix a document's stored assets are served under. */
export const ASSET_URL_PREFIX = '/ui/assets/'

/**
 * Builds the served URL of an asset. It is the ONE place the browser half
 * concatenates this shape, and the prefix comes from the same Go constant the
 * store mints asset references with — so what is written into a document and what
 * is requested for it cannot disagree.
 * @param {string} uuid the document holding the asset
 * @param {string} filename the asset's name within it
 * @returns {string}
 */
export function assetUrl(uuid, filename) {
  return `${ASSET_URL_PREFIX}${uuid}/${filename}`
}
